import{_ as d,a0 as s,w as u,s as l,ao as a,I as e,x as t,a1 as r,A as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const D=JSON.parse('{"title":"如何在 Arch Linux 中安裝 DNSCrypt 和 Unbound | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Arch Linux 中安裝 DNSCrypt 和 Unbound | LCTT (201509) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Arch Linux 中安裝 DNSCrypt 和 Unbound | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Arch Linux 中安裝 DNSCrypt 和 Unbound | LCTT (201509) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201509/20150906 How to Install DNSCrypt and Unbound in Arch Linux","title":"如何在 Arch Linux 中安裝 DNSCrypt 和 Unbound","tag":"201509","desc":""},"relativePath":"201509/20150906 How to Install DNSCrypt and Unbound in Arch Linux.md","filePath":"[post].md"}'),i={name:"201509/20150906 How to Install DNSCrypt and Unbound in Arch Linux.md"};function c(y,n,S,b,C,N){const o=s("Link");return u(),l("div",null,[n[16]||(n[16]=a(`<h1 id="如何在-arch-linux-中安裝-dnscrypt-和-unbound" tabindex="-1">如何在 Arch Linux 中安裝 DNSCrypt 和 Unbound <a class="header-anchor" href="#如何在-arch-linux-中安裝-dnscrypt-和-unbound" aria-label="Permalink to “如何在 Arch Linux 中安裝 DNSCrypt 和 Unbound”">​</a></h1><p><strong>DNSCrypt</strong> 是一個用於對 DNS 客户端和 DNS 解析器之間通信進行加密和驗證的協議。它可以阻止 DNS 欺騙或中間人攻擊。 DNSCrypt 可用於大多數的操作系統，包括 Linux，Windows，MacOSX ，Android 和 iOS。而在本教程中我使用的是內核為4.1的 archlinux。</p><p><strong>Unbound</strong> 是用來解析收到的任意 DNS 查詢的 DNS 緩存服務器。如果用户請求一個新的查詢，unbound 會將其存儲到緩存中，並且當用户再次請求相同的請求時，unbound 將採用已經保存的緩存。這將比第一次請求查詢更快。</p><p>現在我將嘗試安裝“DNSCrypt”，以確保 DNS 的通信的安全，並用“Unbound”加速。</p><h3 id="第一步-安裝-yaourt" tabindex="-1">第一步 - 安裝 yaourt <a class="header-anchor" href="#第一步-安裝-yaourt" aria-label="Permalink to “第一步 - 安裝 yaourt”">​</a></h3><p>Yaourt 是AUR（ARCH 用户倉庫）的輔助工具之一，它可以使用户能夠很容易地從 AUR 安裝程序。 Yaourt 和 pacman 使用相同的語法，你可以使用 yaourt 安裝該程序。下面是安裝 yaourt 的簡單方法：</p><p>1、 用 nano 或者 vi 編輯 arch 倉庫配置文件，存放在“/etc/pacman.conf”中。</p><pre><code>$ nano /etc/pacman.conf
</code></pre><p>2、 在 yaourt 倉庫底部添加，粘貼下面的腳本：</p><pre><code>[archlinuxfr]
SigLevel = Never
Server = http://repo.archlinux.fr/$arch
</code></pre><p>3、 用“Ctrl + x”，接着用“Y”保存。</p><p>4、 接着升級倉庫資料庫並用pacman安裝yaourt：</p><pre><code>$ sudo pacman -Sy yaourt
</code></pre><h3 id="第二步-安裝-dnscrypt-和-unbound" tabindex="-1">第二步 - 安裝 DNSCrypt 和 Unbound <a class="header-anchor" href="#第二步-安裝-dnscrypt-和-unbound" aria-label="Permalink to “第二步 - 安裝 DNSCrypt 和 Unbound”">​</a></h3><p>DNSCrypt 和 unbound 就在 archlinux 倉庫中，你可以用下面的 pacman 命令安裝：</p><pre><code>$ sudo pacman -S dnscrypt-proxy unbound
</code></pre><p>接着在安裝的過程中按下“Y”。</p><h3 id="第三步-安裝-dnscrypt-autoinstall" tabindex="-1">第三步 - 安裝 dnscrypt-autoinstall <a class="header-anchor" href="#第三步-安裝-dnscrypt-autoinstall" aria-label="Permalink to “第三步 - 安裝 dnscrypt-autoinstall”">​</a></h3><p>Dnscrypt-autoinstall 是一個在基於 Linux 的系統上自動安裝和配置 DNSCrypt 的腳本。DNSCrypt 在 AUR 中，因此你必須使用“yaourt”命令來安裝它。</p><pre><code>$ yaourt -S dnscrypt-autoinstall
</code></pre><p>注意 :</p><p>-S = 這和 pacman -S 安裝程序一樣。</p><h3 id="第四步-運行-dnscrypt-autoinstall" tabindex="-1">第四步 - 運行 dnscrypt-autoinstall <a class="header-anchor" href="#第四步-運行-dnscrypt-autoinstall" aria-label="Permalink to “第四步 - 運行 dnscrypt-autoinstall”">​</a></h3><p>用 root 權限運行“dnscrypt-autoinstall”來自動配置 DNSCrypt。</p><pre><code>$ sudo dnscrypt-autoinstall
</code></pre><p>下一步中按下“回車”，接着輸入&quot;Y&quot;來選擇你想使用的 DNS 提供者，我這裏使用不帶日誌和 DNSSEC 的 DNSCrypt.eu。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/08/DNSCrypt-autoinstall.png" alt="DNSCrypt autoinstall"></p><h3 id="第五步-配置-dnscrypt-和-unbound" tabindex="-1">第五步 - 配置 DNSCrypt 和 Unbound <a class="header-anchor" href="#第五步-配置-dnscrypt-和-unbound" aria-label="Permalink to “第五步 - 配置 DNSCrypt 和 Unbound”">​</a></h3><p>1、 打開 dnscrypt 的“/etc/conf.d/dnscrypt-config” ，確認配置文件中“DNSCRYPT_LOCALIP”指向<strong>本地ip</strong>，“DNSCRYPT_LOCALPORT”根據你本人的意願配置，我是用的是<strong>40</strong>端口。</p><pre><code>$ nano /etc/conf.d/dnscrypt-config

DNSCRYPT_LOCALIP=127.0.0.1
DNSCRYPT_LOCALIP2=127.0.0.2
DNSCRYPT_LOCALPORT=40
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/08/DNSCryptConfiguration.png" alt="DNSCrypt Configuration"></p><p>保存並退出。</p><p>2、 現在你用 nano 編輯器編輯“/etc/unbound/”下 unbound 的配置文件：</p><pre><code>$ nano /etc/unbound/unbound.conf
</code></pre><p>3、 在腳本最後添加下面的行：</p><pre><code>do-not-query-localhost: no
forward-zone:
name: &quot;.&quot;
forward-addr: 127.0.0.1@40
</code></pre><p>確保<strong>forward-addr</strong>和DNSCrypt中的“<strong>DNSCRYPT_LOCALPORT</strong>”一致。如你所見，用的是<strong>40</strong>端口。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/08/UnboundConfiguration.png" alt="Unbound Configuration"></p><p>接着保存並退出。</p><h3 id="第六步-運行-dnscrypt-和-unbound-接着添加到開機啓動中" tabindex="-1">第六步 - 運行 DNSCrypt 和 Unbound，接着添加到開機啓動中 <a class="header-anchor" href="#第六步-運行-dnscrypt-和-unbound-接着添加到開機啓動中" aria-label="Permalink to “第六步 - 運行 DNSCrypt 和 Unbound，接着添加到開機啓動中”">​</a></h3><p>請用 root 權限運行 DNSCrypt 和 unbound，你可以用 systemctl 命令來運行：</p><pre><code>$ sudo systemctl start dnscrypt-proxy unbound
</code></pre><p>將服務添加到啓動中。你可以運行“systemctl enable”：</p><pre><code>$ sudo systemctl enable dnscrypt-proxy unbound
</code></pre><p>命令將會創建軟鏈接到“/usr/lib/systemd/system/”目錄的服務。</p><h3 id="第七步-配置-resolv-conf-並重啓所有服務" tabindex="-1">第七步 - 配置 resolv.conf 並重啓所有服務 <a class="header-anchor" href="#第七步-配置-resolv-conf-並重啓所有服務" aria-label="Permalink to “第七步 - 配置 resolv.conf 並重啓所有服務”">​</a></h3><p>resolv.conf 是一個在 linux 中用於配置 DNS 解析器的文件。它是一個由管理員創建的純文本，因此你必須用 root 權限編輯並讓它不能被其他人修改。</p><p>用 nano 編輯器編輯：</p><pre><code>$ nano /etc/resolv.conf
</code></pre><p>並添加本地IP “<strong>127.0.0.1</strong>”。現在用“chattr”命令使他只讀：</p><pre><code>$ chattr +i /etc/resolv.conf
</code></pre><p>注意：</p><p>如果你想要重新編輯，用“chattr -i /etc/resolv.conf”加入寫權限。</p><p>現在你需要重啓 DNSCrypt 和 unbound 和網絡；</p><pre><code>$ sudo systemctl restart dnscrypt-proxy unbound netctl
</code></pre><p>如果你看到錯誤，檢查配置文件。</p><h3 id="測試" tabindex="-1">測試 <a class="header-anchor" href="#測試" aria-label="Permalink to “測試”">​</a></h3><p>1、 測試 DNSCrypt</p>`,58)),e("p",null,[n[1]||(n[1]=t("你可以通過 ",-1)),r(o,{href:"https://dnsleaktest.com/"},{default:p(()=>[...n[0]||(n[0]=[t("https://dnsleaktest.com/",-1)])]),_:1}),n[2]||(n[2]=t(" 來確認 DNSCrypt，點擊“標準測試”或者“擴展測試”，然後等待程序運行結束。",-1))]),n[17]||(n[17]=a(`<p>現在你可以看到 DNSCrypt.eu 就已經與作為 DNS 提供商的 DNSCrypt 協同工作了。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/08/TestingDNSCrypt.png" alt="Testing DNSCrypt"></p><p>2、 測試 Unbound</p><p>現在你應該確保 unbound 可以正確地與“dig”和“drill”命令一起工作。</p><p>這是 dig 命令的結果：</p><pre><code>$ dig linoxide.com
</code></pre><p>我們現在看下結果，“Query time”是“533 msec”：</p><pre><code>;; Query time: 533 msec
;; SERVER: 127.0.0.1#53(127.0.0.1)
;; WHEN: Sun Aug 30 14:48:19 WIB 2015
;; MSG SIZE rcvd: 188
</code></pre><p>再次輸入命令，我們看到“Query time”是“0 msec”。</p><pre><code>;; Query time: 0 msec
;; SERVER: 127.0.0.1#53(127.0.0.1)
;; WHEN: Sun Aug 30 14:51:05 WIB 2015
;; MSG SIZE rcvd: 188
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/08/UnboundTest.png" alt="Unbound Test"></p><p>DNSCrypt 對 DNS 客户端和解析端之間的通訊加密做的很好，並且 Unbound 通過緩存讓相同的請求在另一次請求同速度更快。</p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>DNSCrypt 是一個可以加密 DNS 客户端和 DNS 解析器之間的數據流的協議。 DNSCrypt 可以在不同的操作系統上運行，無論是移動端或桌面端。選擇 DNS 提供商還包括一些重要的事情，應選擇那些提供 DNSSEC 同時沒有日誌的。Unbound 可被用作 DNS 緩存，從而加快解析過程，因為 Unbound 將請求緩存，那麼接下來客户端請求相同的查詢時，unbound 將從緩存中取出保存的值。 DNSCrypt 和 Unbound 是針對安全性和速度的一個強大的組合。</p><hr>`,15)),e("p",null,[n[4]||(n[4]=t("via: ",-1)),r(o,{href:"http://linoxide.com/tools/install-dnscrypt-unbound-archlinux/"},{default:p(()=>[...n[3]||(n[3]=[t("http://linoxide.com/tools/install-dnscrypt-unbound-archlinux/",-1)])]),_:1})]),e("p",null,[n[8]||(n[8]=t("作者：",-1)),r(o,{href:"http://linoxide.com/author/arulm/"},{default:p(()=>[...n[5]||(n[5]=[t("Arul",-1)])]),_:1}),n[9]||(n[9]=t(" 譯者：",-1)),r(o,{href:"https://github.com/geekpi"},{default:p(()=>[...n[6]||(n[6]=[t("geekpi",-1)])]),_:1}),n[10]||(n[10]=t(" 校對：",-1)),r(o,{href:"https://github.com/wxy"},{default:p(()=>[...n[7]||(n[7]=[t("wxy",-1)])]),_:1})]),e("p",null,[n[13]||(n[13]=t("本文由 ",-1)),r(o,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...n[11]||(n[11]=[t("LCTT",-1)])]),_:1}),n[14]||(n[14]=t(" 原創編譯，",-1)),r(o,{href:"https://linux.cn/"},{default:p(()=>[...n[12]||(n[12]=[t("Linux中國",-1)])]),_:1}),n[15]||(n[15]=t(" 榮譽推出",-1))])])}const x=d(i,[["render",c]]);export{D as __pageData,x as default};
